    def sum_of_digits(n):
        total = 0
        is_negative = n < 0
        for digit in str(abs(n)):
            total += int(digit)
        return total if not is_negative else -total

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1

    return count

